#include <cuda_runtime.h>
#include <stdio.h>
#include "denise_gpu.h"
__global__ static void sh_s(int nx,int ny,int st,int spx,int spy,float *vz,float *uz,float *uzx,float *syz,float *sxz,const float *ujp,const float *uip,const float *hc,const float *Kx,const float *ax,const float *bx,const float *Ky,const float *ay,const float *by,float *px,float *py,int mode,int fo,int fw,int fs,int bd,int npx,int npy,int posx,int posy,int grad,float dt,float dh){int x=blockIdx.x*blockDim.x+threadIdx.x,y=blockIdx.y*blockDim.y+threadIdx.y;if(x>=nx||y>=ny)return;float dx=0,dy=0;for(int m=1;m<=fo;m++){dx+=hc[m]*(vz[y*st+x+m]-vz[y*st+x-m+1]);dy+=hc[m]*(vz[(y+m)*st+x]-vz[(y-m+1)*st+x]);}dx*=dt/dh;dy*=dt/dh;int i=x+1,j=y+1;if(!bd&&posx==0&&i<=fw){float q=bx[i]*px[y*spx+x]+ax[i]*dx;px[y*spx+x]=q;dx=dx/Kx[i]+q;}if(!bd&&posx==npx-1&&i>=nx-fw+1){int h=i-nx+2*fw,z=h-1;float q=bx[h]*px[y*spx+z]+ax[h]*dx;px[y*spx+z]=q;dx=dx/Kx[h]+q;}if(posy==0&&!fs&&j<=fw){float q=by[j]*py[y*spy+x]+ay[j]*dy;py[y*spy+x]=q;dy=dy/Ky[j]+q;}if(posy==npy-1&&j>=ny-fw+1){int h=j-ny+2*fw,z=h-1;float q=by[h]*py[z*spy+x]+ay[h]*dy;py[z*spy+x]=q;dy=dy/Ky[h]+q;}int k=y*st+x;sxz[k]+=uip[k]*dx;syz[k]+=ujp[k]*dy;if(grad==1){uz[k]=syz[k];uzx[k]=sxz[k];}else if(grad==2){uz[k]=dy;uzx[k]=dx;}}
extern "C" int denise_gpu_update_s_sh(int a,int b,int c,int d,float **vz,float **uz,float **uzx,float **syz,float **sxz,float **ujp,float **uip,const float *hc,const float *Kx,const float *ax,const float *bx,const float *Ky,const float *ay,const float *by,float **px,float **py,int mode,int fd,int fw,int fs,int bd,int npx,int npy,int posx,int posy,int grad,float dt,float dh){int nx=b-a+1,ny=d-c+1,st=vz[c+1]-vz[c],spx=px[c+1]-px[c],spy=py[2]-py[1];dim3 t(32,8),g((nx+31)/32,(ny+7)/8);sh_s<<<g,t>>>(nx,ny,st,spx,spy,vz[c]+a,uz[c]+a,uzx[c]+a,syz[c]+a,sxz[c]+a,ujp[c]+a,uip[c]+a,hc,Kx,ax,bx,Ky,ay,by,px[c]+1,py[1]+a,mode,fd/2,fw,fs,bd,npx,npy,posx,posy,grad,dt,dh);cudaError_t e=cudaDeviceSynchronize();if(e!=cudaSuccess){fprintf(stderr,"SH stress CUDA: %s\n",cudaGetErrorString(e));return -1;}return 0;}
__global__ static void sh_v(int nx,int ny,int st,int spx,int spy,float *vz,float *vzp,const float *sxz,const float *syz,const float *ri,const float *hc,const float *Kx,const float *ax,const float *bx,const float *Ky,const float *ay,const float *by,float *px,float *py,int sw,int fo,int fw,int fs,int bd,int npx,int npy,int posx,int posy,int grad,float dt,float dh){int x=blockIdx.x*blockDim.x+threadIdx.x,y=blockIdx.y*blockDim.y+threadIdx.y;if(x>=nx||y>=ny)return;float dx=0,dy=0;for(int m=1;m<=fo;m++){dx+=hc[m]*(sxz[y*st+x+m-1]-sxz[y*st+x-m]);dy+=hc[m]*(syz[(y+m-1)*st+x]-syz[(y-m)*st+x]);}int i=x+1,j=y+1;if(!bd&&posx==0&&i<=fw){float q=bx[i]*px[y*spx+x]+ax[i]*dx;px[y*spx+x]=q;dx=dx/Kx[i]+q;}if(!bd&&posx==npx-1&&i>=nx-fw+1){int h=i-nx+2*fw,z=h-1;float q=bx[h]*px[y*spx+z]+ax[h]*dx;px[y*spx+z]=q;dx=dx/Kx[h]+q;}if(posy==0&&!fs&&j<=fw){float q=by[j]*py[y*spy+x]+ay[j]*dy;py[y*spy+x]=q;dy=dy/Ky[j]+q;}if(posy==npy-1&&j>=ny-fw+1){int h=j-ny+2*fw,z=h-1;float q=by[h]*py[z*spy+x]+ay[h]*dy;py[z*spy+x]=q;dy=dy/Ky[h]+q;}int k=y*st+x;float a=ri[k]*(dx+dy)/dh;if(grad==1){if(!sw)vzp[k]=a;else vzp[k]+=vz[k]*dt;}else if(grad==2){if(!sw)vzp[k]=a;else vzp[k]=vz[k];}vz[k]+=dt*a;}
extern "C" int denise_gpu_update_v_sh(int a,int b,int c,int d,float **vz,float **vzp,float **sxz,float **syz,float **ri,const float *hc,const float *Kx,const float *ax,const float *bx,const float *Ky,const float *ay,const float *by,float **px,float **py,int sw,int fd,int fw,int fs,int bd,int npx,int npy,int posx,int posy,int grad,float dt,float dh){int nx=b-a+1,ny=d-c+1,st=vz[c+1]-vz[c],spx=px[c+1]-px[c],spy=py[2]-py[1];dim3 t(32,8),g((nx+31)/32,(ny+7)/8);sh_v<<<g,t>>>(nx,ny,st,spx,spy,vz[c]+a,vzp[c]+a,sxz[c]+a,syz[c]+a,ri[c]+a,hc,Kx,ax,bx,Ky,ay,by,px[c]+1,py[1]+a,sw,fd/2,fw,fs,bd,npx,npy,posx,posy,grad,dt,dh);cudaError_t e=cudaDeviceSynchronize();if(e!=cudaSuccess){fprintf(stderr,"SH velocity CUDA: %s\n",cudaGetErrorString(e));return -1;}return 0;}
